import csv

# Verify RFC 4180 compliance: every row must have exactly 7 fields
with open('outputs/t02_eurostat_raw.csv', newline='') as f:
    reader = csv.reader(f)
    bad_rows = []
    for i, row in enumerate(reader):
        if len(row) != 7:
            bad_rows.append((i, len(row), row))
    if bad_rows:
        print(f'Bad rows: {bad_rows[:5]}')
    else:
        print('All rows have exactly 7 fields - RFC 4180 compliant.')
